import re

def starts_with_word(text, word):
    return re.match(word, text, re.I) is not None

import re

def contains_word(text, word):
    return re.search(word, text, re.I) is not None

import re

def find_years(text):
    return re.findall(r'\d{4}', text)

import re

def extract_numbers(text):
    return [int(n) for n in re.findall(r'\d+', text)]

import re

def is_valid_code(text):
    return re.match(r'^[A-Z]{2}\d{3,4}$', text) is not None

import re

def is_postal_code(text):
    return re.match(r'^\d{5}$', text) is not None

import re

def mask_digits(text):
    return re.sub(r'\d+', '#', text)

import re

def split_fields(text):
    return re.split(r'[,;]', text)
